    // The admin fee is a tenth of what was paid, up to the flat fee. It comes off what was paid, before the refund rate.
    const fee = Math.min(ADMIN_FEE_PENCE, share(paid, 100));
    const afterFee = paid - fee;
    if (afterFee <= 0) {
        return 0;
    }
    // The part earned back is worked out on what is left after the fee.
    const net = share(afterFee, refundRate(daysUntil(cancelDay, startDay)));
    // What would go back is not sent when it is under the minimum.
    return net < MIN_REFUND_PENCE ? 0 : net;
